-- Platform graph: the workflow and roadmap of RabbitOS / rabbitsoftware.io with all connections.
-- NOT APPLIED automatically. Apply by hand in the Supabase SQL editor, then run
-- supabase/seed/platform_graph.seed.sql (generated by scripts/export-platform-graph-sql.mjs).
-- Contents are architecture only: service names, links between them, roadmap titles.
-- No secrets, no personal data, no addresses of private resources.

create table if not exists public.platform_nodes (
  id text primary key,
  label text not null,
  provider text not null check (provider in ('people','cloudflare','gcp','supabase','owner','external')),
  lane smallint not null check (lane between 0 and 9),
  sort_order smallint not null default 0,
  kind text not null,
  status text not null check (status in ('live','fallback','planned','optional')),
  about text not null default ''
);

create table if not exists public.platform_edges (
  id bigint generated always as identity primary key,
  from_id text not null references public.platform_nodes (id) on delete cascade,
  to_id text not null references public.platform_nodes (id) on delete cascade,
  label text not null default '',
  kind text not null default 'request',
  check (from_id <> to_id)
);
create index if not exists platform_edges_from_idx on public.platform_edges (from_id);
create index if not exists platform_edges_to_idx on public.platform_edges (to_id);

create table if not exists public.platform_roadmap (
  id text primary key,
  title text not null,
  status text not null check (status in ('done','waiting','next','later','paused')),
  area text not null default '',
  note text not null default '',
  sort_order smallint not null default 0
);

alter table public.platform_nodes enable row level security;
alter table public.platform_edges enable row level security;
alter table public.platform_roadmap enable row level security;

-- Read-only for everyone; writes only with the service role (which bypasses RLS).
drop policy if exists platform_nodes_read on public.platform_nodes;
create policy platform_nodes_read on public.platform_nodes for select using (true);
drop policy if exists platform_edges_read on public.platform_edges;
create policy platform_edges_read on public.platform_edges for select using (true);
drop policy if exists platform_roadmap_read on public.platform_roadmap;
create policy platform_roadmap_read on public.platform_roadmap for select using (true);

-- One readable tree: each node with what it connects to.
create or replace view public.platform_tree with (security_invoker = true) as
select n.id, n.label, n.provider, n.lane, n.status, n.about,
  coalesce((select jsonb_agg(jsonb_build_object('to', e.to_id, 'label', e.label, 'kind', e.kind) order by e.id)
            from public.platform_edges e where e.from_id = n.id), '[]'::jsonb) as connects_to
from public.platform_nodes n
order by n.lane, n.sort_order;
